{
    sal_Int32 aSlide = mController->getCurrentSlideIndex();

    OString aBuilder = "slide_updated\n" +
        OString::number( aSlide ) +
        "\n\n";

    if ( pTransmitter )
    {
        pTransmitter->addMessage( aBuilder,
                               Transmitter::PRIORITY_HIGH );
    }
